370:    for i, l in enumerate(ls, start):
371:        n = f"{l['seq'] or i:0>2}"   # D1 seq 그대로 (뷰어·인강실·맛보기 문구와 같은 번호. 결번은 인문/자연 트랙 분기의 사실)
372:        t, s2 = l["title"], l.get("subtitle") or ""
373:        if strip and l["kind"] == "passage" and s2:   # 세트 해설은 주제를 표제로, 정형구(단위명 NN번 세트 해설 강의)는 보조행으로
374:            t, s2 = s2, l["title"].replace(strip, "", 1)
375:        sub = f'<span class="m"><span>{E(s2)}</span></span>' if s2 else ""
376:        sample = l["id"] == sample_id
377:        m = f'<span>{mins(l["duration_sec"])}분</span>' + ('<span class="badge seal">맛보기</span>' if sample else "")
