362:def inject_head(s, block):
363:    hs, he = C.head_region(s)
364:    head = s[hs:he]
365:    m = BLOCK_RE.search(head)
366:    if m:
367:        before, after = head[:m.start()], head[m.end():]
368:    else:
369:        before, after = head, ""
370:    for p in DUP_PATTERNS:
371:        before = p.sub("", before)
372:        after = p.sub("", after)
373:    if m:
374:        new_head = before + block + after
375:    else:
376:        tm = re.search(r"</title>[ \t]*\r?\n?", before, re.I)
377:        if tm:
378:            pos = tm.end()
379:            sep = "" if before[tm.start():pos].endswith("\n") else "\n"
380:            new_head = before[:pos] + sep + block + "\n" + before[pos:] + after
381:        else:
382:            new_head = "\n" + block + "\n" + before + after
383:    return s[:hs] + new_head + s[he:]
