386:def inject_aeo(s, answer, rel, warnings):
387:    s = AEO_RE.sub("", s)
388:    if not answer:
389:        return s
390:    mm = re.search(r"<main\b[^>]*>", s, re.I)
391:    if not mm:
392:        warnings.append(f"{rel}: <main> 없음, aeo 단락 미삽입")
393:        return s
394:    txt = C.attr(answer)
395:    if rel.startswith("guidebook/"):
396:        # 문장마다 한 줄 (2026-09-04 건우). 태그를 걷으면 마침표 뒤 공백이 남아 텍스트는 manifest answer 와 같다
397:        txt = re.sub(r"\. (?=\S)", ". <br>", txt)
398:    aeo = f'{C.AEO_BEGIN}<p class="aeo-answer">{txt}</p>{C.AEO_END}'
399:    # 지면이 <!-- aeo-slot --> 을 두면 그 줄 바로 아래 같은 들여쓰기로 삽입 (2026-09-06, 인강 상품면. flex 안·wrap 밖 삽입 회피). 슬롯은 남겨 재실행 시 같은 바이트
400:    slot = re.search(r"^([ \t]*)<!-- aeo-slot -->[ \t]*$", s, re.M)
401:    if slot:
402:        return s[:slot.end()] + "\n" + slot.group(1) + aeo + s[slot.end():]
403:    # pagehead 가 main 안에 있으면 그 블록 끝(부제 뒤)에, 없으면 main 첫 자식으로
404:    ph = re.search(r'<(div|section) class="pagehead"[^>]*>', s[mm.end():], re.I)
405:    if ph:
406:        start = mm.end() + ph.start()
407:        close = re.search(r"</" + ph.group(1) + ">", s[start:], re.I)
408:        if close:
409:            at = start + close.start()
410:            # 닫는 태그 앞 들여쓰기를 걷고 줄 단위로 삽입. 종전(태그 바로 앞 삽입)은 새로 빌드한 면에서 1회째(들여쓰기 잔존)와 2회째 바이트가 달랐다. 이 형태가 종전 2회째(정상 상태)와 바이트 동일 (2026-09-03)
411:            ls = s.rfind("\n", 0, at) + 1
412:            if s[ls:at].strip() == "":
413:                return s[:ls] + "  " + aeo + "\n" + s[at:]
414:            return s[:at] + "  " + aeo + "\n" + s[at:]
415:    return s[:mm.end()] + "\n" + aeo + s[mm.end():]
