418:def sync_title(s, title):
419:    m = re.search(r"(<title[^>]*>)(.*?)(</title>)", s, re.S | re.I)
420:    if not m or not title or C.strip_tags(m.group(2)) == title:
421:        return s
422:    return s[:m.start()] + m.group(1) + C.attr(title) + m.group(3) + s[m.end():]
