unction () {\n     3\t  const API = location.hostname === \"localhost\" || location.protocol === \"file:\"\n     4\t    ? \"http://localhost:8799\" : \"https://api.hyunhak.com\";\n     5\t  const CART_KEY = \"hh_cart_v1\";\n     6\t\n     7\t  async function api(path, opt = {}) {\n     8\t    const res = await fetch(API + path, Object.assign({\n     9\t      credentials: \"include\",\n    10\t      headers: opt.body ? { \"Content-Type\": \"application/json\" } : {},\n    11\t    }, opt));\n    12\t    const data = await res.json().catch(() => ({}));\n    13\t    if (!res.ok) { const e = new Error(data.error || (\"오류 \" + res.status)); e.status = res.status; e.code = data.code; throw e; }\n    14\t    return data;\n    15\t  }\n    16\t\n    17\t  // 세트 id 계약 (PLAN 1-D, 서버와 같은 문자열): 5 단위 x 01~30.\n    18\t  // 쿼리, 카탈로그, localStorage 어디서 온 값이든 이 정규식을 통과한 것만 화면과 주문 body 에 쓴다.\n    19\t  const SET_ID_RE = /^(korea_2027_[hs]|yonsei_2027_[hs]|yonsei_intl_2027_i)(0[1-9]|[12][0-9]|30)$/;\n    20\t  const UNITS = [\"korea-hum\", \"korea-sci\", \"yonsei-hum\", \"yonsei-sci\", \"yonsei-intl\"];\n    21\t  const okSetId = (v) => SET_ID_RE.test(String(v == null ? \"\" : v));\n    22\t  const okUnit = (v) => UNITS.indexOf(String(v == null ? \"\" : v)) >= 0;\n    23\t  // 서버는 주문 1건에 같은 product 를 10줄까지 받는다. 11번째 줄은 주문 전체를 400 으로 떨어뜨린다\n    24\t  const LINE_MAX = 10;\n    25\t\n    26\t  // 유한 정수 강제 + 범위 절단. 화면에 넣는 수는 전부 이 함수를 지난다\n    27\t  function intIn(v, lo, hi, dflt) {\n    28\t    const n = Number(v);\n    29\t    if (!Number.isFinite(n)) return dflt;\n    30\t    const i = Math.trunc(n);\n    31\t    return i < lo ? lo : (i > hi ? hi : i);\n    32\t  }\n    33\t  // localStorage 는 사용자가 고칠 수 있다. 읽는 즉시 스키마를 강제해 화면과 주문 body 양쪽을 지킨다.\n    34\t  // 규격에 안 맞는 줄은 통째로 버린다 (수량에 문자열이 박혀 innerHTML 로 흘러가는 경로 차단)\n    35\t  function normLine(x) {\n    36\t    if (!x || typeof x !== \"object\" || Array.isArray(x)) return null;\n    37\t    const sku = String(x.sku == null ? \"\" : x.sku);\