(a.set_id || \"\") === String(b.set_id || \"\"); }\n    75\t  // {sku,title,price,qty,ship,set_id} 를 받아 {ok, reason, message} 를 돌려준다.\n    76\t  // 담기를 거절하는 세 경우(규격 밖 sku, 세트 없는 낱권, 같은 상품 10줄 초과)는 부르는 면이 안내를 띄운다\n    77\t  function addToCart(item) {\n    78\t    const line = normLine(Object.assign({ qty: 1 }, item));\n    79\t    if (!line) return { ok: false, reason: \"sku\", message: \"담을 수 없는 상품입니다.\" };\n    80\t    if (line.sku === \"passage-single\" && !line.set_id)\n    81\t      return { ok: false, reason: \"set\", message: \"지문 낱권은 지문 목록에서 세트를 고른 뒤 담아 주세요.\" };\n    82\t    const items = cart();\n    83\t    const hit = items.find((x) => sameLine(x, line));\n    84\t    if (hit) {\n    85\t      hit.qty = line.set_id ? 1 : intIn(hit.qty + intIn(item.qty, 1, LINE_MAX, 1), 1, LINE_MAX, 1);\n    86\t      saveCart(items);\n    87\t      trackAdd(line);\n    88\t      return { ok: true };\n    89\t    }\n    90\t    if (items.filter((x) => x.sku === line.sku).length >= LINE_MAX)\n    91\t      return { ok: false, reason: \"limit\",\n    92\t        message: \"같은 상품은 \" + LINE_MAX + \"줄까지 담을 수 있습니다. 먼저 결제하시거나 장바구니에서 줄을 빼 주세요.\" };\n    93\t    items.push(line);\n    94\t    saveCart(items);\n    95\t    trackAdd(line);\n    96\t    return { ok: true };\n    97\t  }\n    98\t  // 전환 계측(2026-09-04): HH_TRACK 는 apply_analytics 가 head 에 정의(GA4 + Meta 픽셀 동시 발화). 없으면 조용히 건너뛴다\n    99\t  function lineItem(x) { return { item_id: x.sku, item_name: x.title, price: x.price, quantity: x.qty || 1 }; }\n   100\t  function track(name, params) { try { if (window.HH_TRACK) HH_TRACK(name, params); } catch (e) {} }\n   101\t  function trackAdd(line) { track(\"add_to_cart\", { currency: \"KRW\", value: line.price * (line.qty || 1), items: [lineItem(line)] }); }\n   102\t  function cartTotal() { return cart().reduce((s, x) => s + x.price * x.qty, 0); }\n   103\t\n   104\t  let _me = null;\n   105\t  async function me(force) {\n   106\t    if (_me !== null && !force) return _me;\n   