5 구현 규격)\n     3\timport { Hono } from \"hono\";\n     4\timport { nowISO, uid, clientIP, rateLimit, signToken, verifyToken, b64url, automatedFor, isExempt, looksAutomated } from \"./util.js\";\n     5\timport { recordAutomationAndStrike } from \"./enforce.js\";\n     6\timport { requireMember } from \"./auth.js\";\n     7\t\n     8\texport const lecture = new Hono();        // /api 마운트\n     9\texport const lectureAdmin = new Hono();   // /admin/api/lectures 마운트 (Access 미들웨어 뒤)\n    10\t\n    11\t// 토큰 TTL 4시간, <video> 는 재생 내내 Range 요청을 이어 보낸다. 리더의 10분을 그대로 쓰면 재생 중 401 스톨.\n    12\t// 세션 id 에 결속되어 로그아웃 즉시 무효, 유출 URL 은 쿠키 없이는 쓸모없다.\n    13\tconst TOKEN_TTL = 4 * 3600;\n    14\tconst RATE_MIN = 0.5, RATE_MAX = 2.0;\n    15\tconst EVENT_KINDS = new Set([\"play\", \"pause\", \"seek\", \"rate\", \"chapter\", \"bookmark\", \"ended\", \"close\", \"error\"]);\n    16\tconst EVENTS_PER_BEAT = 50;\n    17\tconst BOOKMARK_MAX = 100;\n    18\tconst LABEL_MAX = 80, NOTE_MAX = 500;\n    19\tconst WATCHED_CAP = 60;                   // beat 1회 최대 인정 시청량(초)\n    20\tconst STATUSES = new Set([\"empty\", \"ready\", \"hidden\"]);\n    21\tconst DROPOFF_BINS = 20;\n    22\t\n    23\tconst lectureSecret = (env) => `${env.STUDIO_BRIDGE_HMAC}|lecture-v1`;\n    24\t// 세션 결속 키: 웹 쿠키 세션 id 또는 앱 세션 id (둘 다 없는 회원 객체는 없다)\n    25\tconst sessKey = (m) => m.sess_id || (m.app_id ? `app:${m.app_id}` : \"\");\n    26\t// 토큰에는 세션 id 원문 대신 비밀키 HMAC 앞 22자만 싣는다, 쿼리 토큰은 서명일 뿐 암호화가 아니라\n    27\t// URL, 접근 로그로 새면 HttpOnly 쿠키 값까지 노출된다 (Codex r1 #3)\n    28\tasync function sessBind(env, m) {\n    29\t  const t = await signToken({ s: sessKey(m) }, lectureSecret(env));\n    30\t  return t.split(\".\")[1].slice(0, 22);\n    31\t}\n    32\t\n    33\t// ---------- L-5: 동시 시청 상한 (2026-08-30 결재 A안, 리더 v3 밀어내기 모델 이식) ----------\n    34\t// open 이 자기 등록 후 고령 초과분을 밀어낸다. 밀려난 세션은 renew/beat 의 409 code:\"evicted\" 로 차단.\n    35\t// 401/403 은 클라이언트 자동 복구(reopen)가 조용히 재진입해 상한을 무력화하므로 409 = 사람 손 재진입 전용.\n    36\t// 스트림 자체는 검사하지 않아 밀려난 기기의 재생은 최대 beat 주기까지만 이어진다 (검토안 §3-1).\n    37\tconst LEC_ACTIVE_CAP = 3;\n    38\tconst LEC_ACTIVE_WIN = 30 * 60 * 1000;\n    39\tconst LEC_EVICTED_MSG = `다른 기기에서 시청을 시작하여 이 기기의 시청이 중단되었습니다 (동시 ${LEC_ACTIVE_CAP}기기 한도). 계속 보려면 다시 열어 주세요`;\n    40\t// 자기 등록 + 밀어내기 3문, open 의 시청 세션 생성과 같은 batch 에 합류시켜 단일 트랜잭션으로 만든다\n    41\t// (등록, 밀어내기만 커밋되고 세션 생성이 실패하면, 정상 기기는 축출됐는데 호출자는 토큰을 못 받는다, Codex 후속 r1 #14).\n    42\t// 자기 지문은 밀어내기에서 명시 제외 (reader v3 Codex B-2 승계). lecture_id 는 이 지문의 마지막 강의 기록.\n    43\tfunction lecActiveStmts(c, m, lectureId, sf) {\n    44\t  const now = nowISO();\n    45\t  const stale = new Date(Date.now() - LEC_ACTIVE_WIN).toISOString();\n    46\t  return [\n    47\t    c.env.DB.prepare(\n    48\t      // last_ts 단조, 지연된 open 커밋이 그 사이 touch 된 최신 last_ts 를 과거로 되돌려\n    49\t      // 활성 기기를 최고령으로 오판하게 하지 않는다 (r2 R5)\n    50\t      `INSERT INTO lecture_active(member_id,sess_fp,first_ts,last_ts,lecture_id) VALUES(?,?,?,?,?)\n    51\t       ON CONFLICT(member_id,sess_fp) DO UPDATE SET\n    52\t         lecture_id=CASE WHEN last_ts<excluded.last_ts THEN excluded.lecture_id ELSE lecture_id END,\n    53\t         last_ts=CASE WHEN last_ts<excluded.last_ts THEN excluded.last_ts ELSE last_ts END`\n    54\t    ).bind(m.id, sf, now, now, lectureId),\n    55\t    c.env.DB.prepare(\"DELETE FROM lecture_active WHERE member_id=? AND sess_fp<>? AND last_ts<?\").bind(m.id, sf, stale),\n    56\t    c.env.DB.prepare(\n    57\t      `DELETE FROM lecture_active WHERE member_id=?1 AND sess_fp<>?2 AND sess_fp NOT IN (\n    58\t         SELECT sess_fp FROM lecture_active WHERE member_id=?1 AND sess_fp<>?2 ORDER BY last_ts DESC, sess_fp DESC LIMIT ?3\n    59\t       ) RETURNING sess_fp, lecture_id`\n    60\t    ).bind(m.id, sf, LEC_ACTIVE_CAP - 1),\n    61\t  ];\n    62\t}\n    63\t// 밀어내기 원장, 피해 지문이 마지막으로 보던 강의를 기록한다 (Codex 후속 r1 #15)\n    64\t// await, waitUntil 로 미루면 실패가 조용히 삼켜져 축출은 성립했는데 원장이 없다 (r2 R7)\n    65\tasync function lecLogEvicted(c, m, evicted) {\n    66\t  const now = nowISO();\n    67\t  for (const e of (evicted || []))\n    68\t    await c.env.DB.prepare(\n    69\t      \"INSERT INTO lecture_events(session_id,member_id,lecture_id,kind,pos_sec,value,ts) VALUES('evict',?,?,'evict',NULL,?,?)\"\n    70\t    ).bind(m.id, e.lecture_id || null, e.sess_fp.slice(0, 8), now).run();\n    71\t}\n    72\t// 검사와 활동 갱신(touch)을 분리한다, 검사 실패 요청(403/409/429)이 last_ts 를 갱신해\n    73\t// 정상 기기를 밀어내면 안 되므로, touch 는 호출자가 전 검증 통과 뒤에만 부른다 (Codex 후속 r1 #13).\n    74\tasync function lecActiveRow(c, m, sf) {\n    75\t  return c.env.DB.prepare(\"SELECT last_ts FROM lecture_active WHERE member_id=? AND sess_fp=?\").bind(m.id, sf).first();\n    76\t}\n    77\t// 활동 신호 1분 스로틀 + 단조 갱신 (reader v3 승계). await, waitUntil 로 미루면 정상 beat 직후의\n    78\t// 동시 open 이 갱신 전 last_ts 를 보고 방금 활동한 자기 행을 밀어낸다 (Codex 후속 r1 #12).\n    79\t// lecture_id 도 함께, 다른 강의를 연 뒤 옛 탭에서 계속 본 기기의 피해 강의가 옛 open 값으로 굳지 않게 (r2 R7)\n    80\tasync function lecTouch(c, m, sf, row, lectureId) {\n    81\t  if (Date.now() - Date.parse(row.last_ts) > 60_000) {\n    82\t    await c.env.DB.prepare(\n    83\t      `UPDATE lecture_active SET last_ts=CASE WHEN last_ts<?1 THEN ?1 ELSE last_ts END,\n    84\t         lecture_id=COALESCE(?4, lecture_id) WHERE member_id=?2 AND sess_fp=?3`\n    85\t    ).bind(nowISO(), m.id, sf, lectureId || null).run();\n    86\t  } else if (lectureId) {\n    87\t    // throttle 은 last_ts 쓰기 빈도 제어이지 피해 강의 정확도를 깎는 장치가 아니다 (r3 REQ5)\n    88\t    // 1분 안에 다른 강의로 활동이 옮겨가도 lecture_id 는 즉시 따라간다 (변경시에만 쓰기라 증폭 없음)\n    89\t    await c.env.DB.prepare(\n    90\t      \"UPDATE lecture_active SET lecture_id=?1 WHERE member_id=?2 AND sess_fp=?3 AND lecture_id<>?1\"\n    91\t    ).bind(lectureId, m.id, sf).run();\n    92\t  }\n    93\t}\n    94\t\n    95\tconst SESSION_REUSE_MIN = 30;             // 같은 강의를 30분 안에 다시 열면 같은 시청 회차 (새로고침, 복구가 회차를 부풀리지 않게, Codex r1 #7)\n    96\tconst RATES = [0.5, 0.75, 1, 1.25, 1.5, 1.75, 2];\n    97\tconst snapRate = (r) => RATES.reduce((a, b) => (Math.abs(b - r) < Math.abs(a - r) ? b : a), 1);\n    98\tconst BEAT_BODY_MAX = 16 * 1024;\n    99\t\n   100\tconst num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };\n   101\tconst clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));\n   102\tconst round2 = (v) => Math.round(v * 100) / 100;\n   103\t\n   104\t// ---------- 로드, 판정 ----------\n   105\tasync function loadLecture(c, id) {\n   106\t  if (!id || typeof id !== \"string\" || id.length > 80) return null;\n   107\t  return c.env.DB.prepare(\"SELECT * FROM lectures WHERE id=?\").bind(id).first();\n   108\t}\n   109\tasync function chaptersOf(c, id) {\n   110\t  return (await c.env.DB.prepare(\"SELECT seq, start_sec, title FROM lecture_chapters WHERE lecture_id=? ORDER BY seq\").bind(id).all()).results;\n   111\t}\n   112\tasync function bookmarksOf(c, memberId, id) {\n   113\t  return (await c.env.DB.prepare(\n   114\t    \"SELECT id, position_sec, label, note, created_at FROM lecture_bookmarks WHERE member_id=? AND lecture_id=? ORDER BY position_sec, created_at\"\n   115\t  ).bind(memberId, id).all()).results;\n   116\t}\n   117\tasync function progressOf(c, memberId, id) {\n   118\t  return c.env.DB.prepare(\n   119\t    \"SELECT position_sec, max_position_sec, watched_sec, rate, view_count, completed_at, updated_at FROM lecture_progress WHERE member_id=? AND lecture_id=?\"\n   120\t  ).bind(memberId, id).first();\n   121\t}\n   122\t// 회원의 유효 권리 범위 전부 (목록에서 N회 조인 대신 1회 로드)\n   123\tasync function accessRows(c, memberId) {\n   124\t  return (await c.env.DB.prepare(\n   125\t    `SELECT la.scope, la.unit_code, la.set_id FROM lecture_access la JOIN entitlements e ON e.id = la.entitlement_id\n   126\t     WHERE e.member_id=? AND (e.expires_at IS NULL OR e.expires_at > ?)`\n   127\t  ).bind(memberId, nowISO()).all()).results;\n   128\t}\n   129\tfunction coversLecture(rows, lec) {\n   130\t  if (lec.access === \"member\") return true;\n   131\t  for (const r of rows) {\n   132\t    if (r.scope === \"common\" && lec.kind === \"common\") return true;\n   133\t    if (r.scope === \"unit\" && lec.kind === \"unit\" && r.unit_code === lec.unit_code) return true;\n   134\t    if (r.scope === \"unit_passages\" && lec.kind === \"passage\" && r.unit_code === lec.unit_code) return true;\n   135\t    if (r.scope === \"passage\" && lec.kind === \"passage\" && r.set_id === lec.passage_set_id) return true;\n   136\t  }\n   137\t  return false;\n   138\t}\n   139\tasync function hasAccess(c, memberId, lec) {\n   140\t  if (lec.access === \"member\") return true;\n   141\t  const row = await c.env.DB.prepare(\n   142\t    `SELECT 1 AS ok FROM lecture_access la JOIN entitlements e ON e.id = la.entitlement_id\n   143\t     WHERE e.member_id=? AND (e.expires_at IS NULL OR e.expires_at > ?)\n   144\t       AND ( (la.scope='common'        AND ?='common')\n   145\t          OR (la.scope='unit'          AND ?='unit'    AND la.unit_code=?)\n   146\t          OR (la.scope='unit_passages' AND ?='passage' AND la.unit_code=?)\n   147\t          OR (la.scope='passage'       AND ?='passage' AND la.set_id=?) ) LIMIT 1`\n   148\t  ).bind(memberId, nowISO(), lec.kind, lec.kind, lec.unit_code || \"\", lec.kind, lec.unit_code || \"\", lec.kind, lec.passage_set_id || \"\").first();\n   149\t  return !!row;\n   150\t}\n   151\t// 이어보기 지점: 완주했고 끝 근처면 처음부터\n   152\tfunction resumeOf(p, dur) {\n   153\t  if (!p) return 0;\n   154\t  const pos = num(p.position_sec);\n   155\t  if (p.completed_at && dur && pos >= dur * 0.95) return 0;\n   156\t  return round2(pos);\n   157\t}\n   158\tconst publicLecture = (l) => ({\n   159\t  id: l.id, kind: l.kind, unit_code: l.unit_code, passage_set_id: l.passage_set_id, seq: l.seq,\n   160\t  title: l.title, subtitle: l.subtitle, duration_sec: l.duration_sec, status: l.status, access: l.access,\n   161\t  published_at: l.published_at, has_script: !!l.script_path,\n   162\t});\n   163\t\n   164\t// ---------- 목록, 요약, 상세 ----------\n   165\tlecture.get(\"/lectures\", requireMember(async (c) => {\n   166\t  const m = c.get(\"member\");\n   167\t  const unit = c.req.query(\"unit\"), set = c.req.query(\"set\");\n   168\t  let sql = \"SELECT * FROM lectures WHERE status<>'hidden'\";\n   169\t  const binds = [];\n   170\t  if (unit) { sql += \" AND unit_code=?\"; binds.push(unit); }\n   171\t  if (set) { sql += \" AND passage_set_id=?\"; binds.push(set); }\n   172\t  sql += \" ORDER BY kind, unit_code, seq, title\";\n   173\t  const rows = (await c.env.DB.prepare(sql).bind(...binds).all()).results;\n   174\t  const acc = await accessRows(c, m.id);\n   175\t  const prog = (await c.env.DB.prepare(\n   176\t    \"SELECT lecture_id, position_sec, view_count, completed_at, updated_at FROM lecture_progress WHERE member_id=?\"\n   177\t  ).bind(m.id).all()).results;\n   178\t  const pmap = Object.fromEntries(prog.map((p) => [p.lecture_id, p]));\n   179\t  const out = rows.map((l) => {\n   180\t    const p = pmap[l.id];\n   181\t    return { ...publicLecture(l), entitled: coversLecture(acc, l),\n   182\t      progress: p ? { position_sec: round2(num(p.position_sec)), view_count: p.view_count, completed: !!p.completed_at, updated_at: p.updated_at } : null };\n   183\t  });\n   184\t  return c.json({ lectures: out });\n   185\t}));\n   186\t\n   187\t// 공개 요약 (SPEC §6 문구 3단 분기: N=0 준비 중 / 0<N<전체 순차 공개 / N=전체 전체 포함). hidden 은 ready 에서 제외\n   188\tlecture.get(\"/lectures/summary\", async (c) => {\n   189\t  const unit = c.req.query(\"unit\") || null, set = c.req.query(\"set\") || null, kind = c.req.query(\"kind\") || null;\n   190\t  let where = \"1=1\"; const binds = [];\n   191\t  if (unit) { where += \" AND unit_code=?\"; binds.push(unit); }\n   192\t  if (set) { where += \" AND passage_set_id=?\"; binds.push(set); }\n   193\t  if (kind) { where += \" AND kind=?\"; binds.push(kind); }\n   194\t  const r = await c.env.DB.prepare(\n   195\t    `SELECT COUNT(*) total, SUM(CASE WHEN status='ready' THEN 1 ELSE 0 END) ready FROM lectures WHERE ${where}`\n   196\t  ).bind(...binds).first();\n   197\t  return c.json({ unit, set, kind, total: r?.total || 0, ready: r?.ready || 0, as_of: nowISO().slice(0, 10) });\n   198\t});\n   199\t\n   200\t// 공개 인강 상태 (PLAN s30 1-D, 2026-09-02): 회원 불요, 단위 목록의 상태만 노출.\n   201\t// 자산 키(r2_key 등)는 SELECT 목록에 아예 넣지 않는다, 필드 추가 실수로 새어 나가지 않게.\n   202\tconst PUBLIC_UNIT_RE = /^[a-z]+(-[a-z]+)+$/;\n   203\t// kind 는 폐쇄 어휘 3종 (Codex lecture_link r1 #9). 임의 문자열을 그대로 바인드하면 비회원 반복 조회가\n   204\t// 인덱스를 못 타는 조건으로 들어온다. 상한 500행도 같은 이유다 (한 단위 최대 39행이라 실사용 여유).\n   205\tconst PUBLIC_KINDS = new Set([\"common\", \"unit\", \"passage\"]);\n   206\tconst PUBLIC_LIMIT = 500;\n   207\tlecture.get(\"/lectures/public\", async (c) => {\n   208\t  const unit = c.req.query(\"unit\");\n   209\t  if (!unit || !PUBLIC_UNIT_RE.test(unit)) return c.json({ error: \"unit 형식이 올바르지 않습니다\" }, 400);\n   210\t  const kind = c.req.query(\"kind\") || null;\n   211\t  if (kind && !PUBLIC_KINDS.has(kind)) return c.json({ error: \"kind 형식이 올바르지 않습니다\" }, 400);\n   212\t  let sql = `SELECT id, kind, unit_code, passage_set_id, seq, title, subtitle, duration_sec, status, published_at\n   213\t             FROM lectures WHERE status<>'hidden' AND unit_code=?`;\n   214\t  const binds = [unit];\n   215\t  if (kind) { sql += \" AND kind=?\"; binds.push(kind); }\n   216\t  sql += ` ORDER BY kind, seq LIMIT ${PUBLIC_LIMIT}`;\n   217\t  const rows = (await c.env.DB.prepare(sql).bind(...binds).all()).results;\n   218\t  return c.json({ unit, lectures: rows });\n   219\t});\n   220\t\n   221\t// ---------- 열람 시작: 토큰 + 시청 세션 1행 + 회차 +1 ----------\n   222\tlecture.post(\"/lecture/open\", requireMember(async (c) => {\n   223\t  const m = c.get(\"member\");\n   224\t  const { id, sig } = await c.req.json().catch(() => ({}));\n   225\t  // 자동화 = UA 지문 OR 클라이언트 자기신고 신호 2개 이상. 예외 회원(automation_exempt)은 통과 (2026-08-30, 리더와 같은 규칙)\n     1\t<!doctype html>\n     2\t<html lang=\"ko\">\n     3\t<head>\n     4\t<meta charset