-top:var(--s3);max-width:var(--measure)}\n   366\t\n   367\t/* ═══ [2b] 하위 페이지 컴포넌트 ═══ */\n   368\t/* 페이지 머리 */\n   369\t:where(body.v2) .phead{padding:var(--s6) 0 var(--s5)}\n   370\t:where(body.v2) .phead.tight{padding:var(--s5) 0 var(--s4)}\n   371\t:where(body.v2) .phead h1{font-size:var(--t-h1);margin-top:var(--s3)}\n   372\t:where(body.v2) .phead .lede{margin-top:var(--s3);font-size:var(--t-md);color:var(--body);max-width:var(--measure);line-height:1.6}\n   373\t:where(body.v2) .phead .lede a{text-decoration:underline;text-underline-offset:4px;text-decoration-color:var(--hair)}\n   374\t:where(body.v2) .phead .facts{margin-top:var(--s5)}\n   375\t:where(body.v2) .phead .acts{margin-top:var(--s4);display:flex;gap:var(--s3);flex-wrap:wrap;align-items:center}\n   376\t:where(body.v2) .phead .han{font-family:var(--serif);font-weight:300;font-size:var(--t-sm);color:var(--gray);margin-top:10px;letter-spacing:.06em}\n   377\t\n   378\t/* 2단 (본문 + 사이드). 열 구성은 여기서만 정한다 (감사 D1: 페이지 재선언 금지) */\n   379\t:where(body.v2) .lay{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:var(--s6);align-items:start;padding-block:var(--s5) var(--s8)}\n   380\t:where(body.v2) .lay.rev{grid-template-columns:260px minmax(0,1fr)}\n   381\t:where(body.v2) .lay.narrow{max-width:760px;grid-template-columns:1fr}\n   382\t:where(body.v2) .side{position:sticky;top:calc(var(--hd-h) + var(--s4));display:flex;flex-direction:column;gap:var(--s3)}\n   383\t:where(body.v2) .box{background:var(--mat);border-radius:var(--r-md);padding:var(--s4)}\n   384\t:where(body.v2) .box h3{font-family:var(--mono);font-size:var(--t-xs);font-weight:500;letter-spacing:var(--tr-label);color:var(--gray);margin-bottom:10px}\n   382\t            new_head = \"\\n\" + block + \"\\n\" + before + after\n   383\t    return s[:hs] + new_head + s[he:]\n   384\t\n   385\t\n   386\tdef inject_aeo(s, answer, rel, warnings):\n   387\t    s = AEO_RE.sub(\"\", s)\n   388\t    if not answer:\n   389\t        return s\n   390\t    mm = re.search(r\"<main\\b[^>]*>\", s, re.I)\n   391\t    if not mm:\n   392\t        warnings.append(f\"{rel}: <main> 없음, aeo 단락 미삽입\")\n   393\t        return s\n   394\t    txt = C.attr(answer)\n   395\t    if rel.startswith(\"guidebook/\"):\n   396\t        # 문장마다 한 줄 (2026-09-04 건우). 태그를 걷으면 마침표 뒤 공백이 남아 텍스트는 manifest answer 와 같다\n   397\t        txt = re.sub(r\"\\. (?=\\S)\", \". <br>\", txt)\n   398\t    aeo = f'{C.AEO_BEGIN}<p class=\"aeo-answer\">{txt}</p>{C.AEO_END}'\n   399\t    # pagehead 가 main 안에 있으면 그 블록 끝(부제 뒤)에, 없으면 main 첫 자식으로\n   400\t    ph = re.search(r'<(div|section) class=\"pagehead\"[^>]*>', s[mm.end():], re.I)\n   401\t    if ph:\n   402\t        start = mm.end() + ph.start()\n   403\t        close = re.search(r\"</\" + ph.group(1) + \">\", s[start:], re.I)\n   404\t        if close:\n   405\t            at = start + close.start()\n   406\t            # 닫는 태그 앞 들여쓰기를 걷고 줄 단위로 삽입. 종전(태그 바로 앞 삽입)은 새로 빌드한 면에서 1회째(들여쓰기 잔존)와 2회째 바이트가 달랐다. 이 형태가 종전 2회째(정상 상태)와 바이트 동일 (2026-09-03)\n   407\t            ls = s.rfind(\"\\n\", 0, at) + 1\n   408\t            if s[ls:at].strip() == \"\":\n   409\t                return s[:ls] + \"  \" + aeo + \"\\n\" + s[at:]\n   410\t            return s[:at] + \"  \" + aeo + \"\\n\" + s[at:]\n   411\t    return s[:mm.end()] + \"\\n\" + aeo + s[mm.end():]\n   412\t\n   413\t\n   414\tdef sync_title(s, title):\n   415\t    m = re.search(r\"(<title[^>]*>)(.*?)(</title>)\", s, re.S | re.I)\n   416\t    if not m or not title or C.strip_tags(m.group(2)) == title:\n   417\t        return s\n   418\t    return s[:m.start()] + m.group(1) + C.attr(title) + m.group(3) + s[m.end():]\npastexam.html:98:  <!-- aeo --><p class=\"aeo-answer\">기출 체험판은 회원 계정당 한 번 신청하며, 신청한 시점부터 48시간 동안 보안 리더에서 열람합니다. 인쇄와 원본 파일 내려받기는 제공하지 않습니다.</p><!-- /aeo -->\nsupport.html:143:  <!-- aeo --><p class=\"aeo-answer\">고객센터에서는 1:1 문의 접수, 환불 규정 안내, 자주 묻는 질문을 다룹니다. 문의는 admin@hyunhak.com 으로도 받습니다.</p><!-- /aeo -->\nnotice.html:89:  <!-- aeo --><p class=\"aeo-answer\">현학적 연구소 공지는 가이드북 갱신, 스튜디오 일정, 서비스 변경 사항을 날짜순으로 기록합니다.</p><!-- /aeo -->\nlectures/yonsei-hum.html:132:<!-- aeo --><p class=\"aeo-answer\">연세대 활동우수 인문통합 풀이법 인강은 공통 풀이 4편과 단위 강의, 세트 해설 30편으로 구성되며 단위 전권 이용권에 포함되어 구매일부터 3개월 시청합니다.</p><!-- /aeo -->\nlectures/common.html:132:<!-- aeo --><p class=\"aeo-answer\">공통 풀이 인강은 연세대, 고려대 제시문 면접 다섯 단위에 공통인 풀이 절차 4편으로 220,000원에 3개월 시청하며, 단위 전권 이용권에는 이미 포함되어 있습니다.</p><!-- /aeo -->\nlectures/yonsei-sci.html:132:<!-- aeo --><p class=\"aeo-answer\">연세대 활동우수 자연 풀이법 인강은 공통 풀이 4편과 단위 강의, 세트 해설 30편으로 구성되며 단위 전권 이용권에 포함되어 구매일부터 3개월 시청합니다.</p><!-- /aeo -->\nfaq.html:88:  <!-- aeo --><p class=\"aeo-answer\">가이드북은 구매 후 보안 리더로 열람하며 원본 파일은 제공하지 않습니다. 스튜디오는 지문 1편에 5회 응시하고 회차마다 첨삭이 붙습니다.</p><!-- /aeo -->\nabout.html:99:  <!-- aeo --><p class=\"aeo-answer\">현학적 연구소는 대입 면접 자료를 만드는 곳으로, 모집요강, 선행학습영향평가 보고서, 수험생 후기에서 모은 질문으로 가이드북 31권과 연세대, 고려대 스튜디오를 입시 컨설턴트 13년차가 편집합니다.</p><!-- /aeo -->\nb2b.html:91:  <!-- aeo --><p class=\"aeo-answer\">스쿨 플랜은 학원이 제시문 면접 스튜디오 좌석을 5개 이상 도입하는 플랜입니다. 추가 좌석 단가는 315,000원에서 240,000원까지 내려가고, 강사 계정과 학생 리포트 관리가 포함됩니다.</p><!-- /aeo -->\nlectures.html:149:    <div class=\"acts rv\"><a class=\"btn\" href=\"#ot\">인강 OT 와 맛보기 <span class=\"ar\" aria-hidden=\"true\">→</span></a><a class=\"btn ghost\" href=\"classroom.html\">인강실</a>  <!-- aeo --><p class=\"aeo-answer\">현학적 연구소 인강은 연세대, 고려대 제시문 면접 풀이법 강의입니다. 공통 풀이 4편과 단위 강의, 세트 해설을 단위 전권에 포함해 3개월 시청합니다.</p><!-- /aeo -->\nlibrary.html:92:  <!-- aeo --><p class=\"aeo-answer\">자료실의 학교별 2027 서류기반면접 가이드북은 구매한 계정으로 보안 리더에서 열람하며, 원본 파일은 제공하지 않습니다.</p><!-- /aeo -->\nprograms/guidebook.html:115:.hero .aeo-answer{font-size:var(--t-sm);color:var(--gray);margin-top:var(--s4);max-width:34em}\nprograms/guidebook.html:411:  <!-- aeo --><p class=\"aeo-answer\">대학별 면접 가이드북 2027은 서류기반 면접(생기부 면접) 준비서로 31개 대학 31권, 다섯 부 구성입니다. 면접 기출문제와 생기부 예상 질문 규칙을 담았고 권당 33,000원.</p><!-- /aeo -->\nlectures/korea-hum.html:132:<!-- aeo --><p class=\"aeo-answer\">고려대 계열적합 인문 풀이법 인강은 공통 풀이 4편과 단위 강의, 세트 해설 30편으로 구성되며 단위 전권 이용권에 포함되어 구매일부터 3개월 시청합니다.</p><!-- /aeo -->\ninterview.html:29:<script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@graph\":[{\"@type\":\"Organization\",\"@id\":\"https://hyunhak.com/#organization\",\"name\":\"현학적 연구소\",\"alternateName\":\"玄學的 硏究所\",\"url\":\"https://hyunhak.com/\",\"logo\":{\"@type\":\"ImageObject\",\"url\":\"https://hyunhak.com/assets/photo/art_figure.png\"},\"email\":\"admin@hyunhak.com\",\"telephone\":\"+82-70-8098-0671\",\"taxID\":\"293-38-01827\",\"address\":{\"@type\":\"PostalAddress\",\"streetAddress\":\"테헤란로 70길 12, 402-941A호\",\"addressLocality\":\"강남구\",\"addressRegion\":\"서울특별시\",\"addressCountry\":\"KR\"},\"founder\":{\"@id\":\"https://hyunhak.com/#author\"},\"sameAs\":[]},{\"@type\":\"Person\",\"@id\":\"https://hyunhak.com/#author\",\"name\":\"현건우\",\"url\":\"https://hyunhak.com/about.html\",\"worksFor\":{\"@id\":\"https://hyunhak.com/#organization\"},\"alternateName\":\"현학자\",\"jobTitle\":\"입시 컨설턴트\",\"description\":\"입시 컨설턴트 13년차. 대학별 서류기반면접 가이드북 31권과 연세대, 고려대 제시문 면접 스튜디오를 한 사람이 편집한다.\",\"alumniOf\":{\"@type\":\"CollegeOrUniversity\",\"name\":\"고려대학교\"}},{\"@type\":\"WebSite\",\"@id\":\"https://hyunhak.com/#website\",\"url\":\"https://hyunhak.com/\",\"name\":\"현학적 연구소\",\"alternateName\":\"玄學的 硏究所\",\"publisher\":{\"@id\":\"https://hyunhak.com/#organization\"},\"inLanguage\":\"ko-KR\"},{\"@type\":\"BreadcrumbList\",\"@id\":\"https://hyunhak.com/interview.html#breadcrumb\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"name\":\"현학적 연구소\",\"item\":\"https://hyunhak.com/\"},{\"@type\":\"ListItem\",\"position\":2,\"name\":\"면접 형태 판정표\",\"item\":\"https://hyunhak.com/interview.html\"}]},{\"@type\":\"WebPage\",\"@id\":\"https://hyunhak.com/interview.html#webpage\",\"url\":\"https://hyunhak.com/interview.html\",\"name\":\"대학별 면접 형태 판정표 2027, 38개 대학 서류기반 면접과 제시문 면접, 전형별 판정과 준비 자료\",\"description\":\"38개 대학의 전형별 면접 형태를 한 표로 판정합니다. 서류기반 면접(생기부 면접), 제시문 면접, MMI 와 혼합형을 가르고 대학마다 면접 가이드북과 스튜디오로 잇습니다. 현학적 연구소 편집.\",\"isPartOf\":{\"@id\":\"https://hyunhak.com/#website\"},\"inLanguage\":\"ko-KR\",\"primaryImageOfPage\":{\"@type\":\"ImageObject\",\"url\":\"https://hyunhak.com/assets/photo/og_aigen.jpg\"},\"breadcrumb\":{\"@id\":\"https://hyunhak.com/interview.html#breadcrumb\"},\"author\":{\"@id\":\"https://hyunhak.com/#author\"},\"publisher\":{\"@id\":\"https://hyunhak.com/#organization\"},\"speakable\":{\"@type\":\"SpeakableSpecification\",\"cssSelector\":[\".aeo-answer\",\".facts\"]},\"dateModified\":\"2026-09-04\",\"keywords\":\"대학 면접 형태, 서류기반 면접, 생기부 면접, 제시문 면접, MMI 면접, 학종 면접, 대입 면접 준비, 대입 면접컨설팅, 대입 모의면접, 모의면접, 면접컨설팅, 면접 기출문제, 면접 예상문제, 면접 예상 질문, 대학별 면접 가이드북 2027, 아주대 면접, 가톨릭대 면접, 중앙대 면접, 동국대 면접, 이화여대 면접, 가천대 면접, 한국외대 면접, 인하대 면접, 경희대 면접, 경북대 면접, 건국대 면접, 국민대 면접, 고려대 면접, 고대 면접, 광운대 면접, 경기대 면접, 명지대 면접, 부산대 면접, 세종대 면접, 서울과기대 면접, 성균관대 면접, 서울대 면접, 숙명여대 면접, 숭실대 면접, 성신여대 면접, 서울시립대 면접, 연세대 면접, 연대 면접, DGIST 면접, 단국대 면접, 덕성여대 면접, 동덕여대 면접, 동아대 면접, 부경대 면접, 삼육대 면접, 서울여대 면접, 울산대 면접, 인천대 면접, 한양대 ERICA 면접, 홍익대 면접\"},{\"@type\":\"FAQPage\",\"@id\":\"https://hyunhak.com/interview.html#faq\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"서류기반 면접과 생기부 면접은 같은 말인가요?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"같습니다. 내 생활기록부가 문제지인 면접이라 생기부 면접, 학종 면접, 인성 면접으로도 부릅니다. 표의 34개 대학이 이 형태입니다. 준비는 대학별 면접 가이드북 2027의 기출과 생기부 예상 질문 규칙으로 합니다.\"}},{\"@type\":\"Question\",\"name\":\"제시문 면접은 무엇이 다른가요?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"면접장에서 받은 글과 발문을 정해진 시간 안에 읽고 답하는 면접입니다. 연세대 활동우수형과 고려대 계열적합전형이 대표적입니다. 제시문 면접 스튜디오에서 실전 규격으로 모의면접을 보고 첨삭 세 단을 받습니다.\"}},{\"@type\":\"Question\",\"name\":\"면접 기출문제는 어디서 보나요?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"판매 중인 31개 대학 가이드북 3부에 선배 후기에서 회수한 면접 기출문제 3,934문이 유형별로 실려 있습니다. 연세대와 고려대 2026 면접 기출은 체험판에서 48시간 무료로 봅니다.\"}},{\"@type\":\"Question\",\"name\":\"면접 예상문제는 어떻게 만드나요?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"가이드북 4부의 전환 규칙이 내 생기부 기재를 면접 예상 질문으로 바꿉니다. 규칙마다 기재 조건과 실제 기출, 꼬리질문이 붙어 그대로 내 질문지가 됩니다.\"}},{\"@type\":\"Question\",\"name\":\"대입 면접컨설팅이나 대입 모의면접도 하나요?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"별도 1:1 면접컨설팅 상품은 없습니다. 서류기반 면접은 입시 컨설턴트 13년차가 편집한 가이드북으로, 제시문 면접은 스튜디오에서 촬영 응시와 첨삭 세 단의 모의면접으로 준비합니다.\"}},{\"@type\":\"Question\",\"name\":\"MMI 면접도 있나요?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"서울대 일반전형 의대 등 일부 전형은 MMI 이고 의약학 계열에는 서류기반과 제시문을 섞는 혼합형이 있습니다. 표에서 전형별 형태를 확인합니다. 해당 대학 가이드북 1부 판정표가 지원 전형의 형태를 가릅니다.\"}},{\"@type\":\"Question\",\"name\":\"가천대학교 면접은 어떤 형태인가요?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"가천대 가천바람개비는 서류기반 면접입니다. 가천의약학은 서류기반 면접. 준비는 가천대 면접 가이드북 2027의 기출과 생기부 예상 질문 규칙으로 합니다.\"}},{\"@type\":\"Question\",\"name\":\"가톨릭대학교 면접은 어떤 형태인가요?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"가톨릭대 잠재능력우수자면접전형은 서류기반 면접입니다. 학교장추천전형은 서류기반 면접. 학교장추천전형 의예과는 서류기반과 인적성 제시문 혼합 면접. 준비는 가톨릭대 면접 가이드북 2027의 기출과 생기부 예상 질문 규칙으로 합니다.\"}},{\"@type\":\"Question\",\"name\":\"건국대학교 면접은 어떤 형태인가요?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"건국대 KU자기추천은 서류기반 면접입니다. 준비는 건국대 면접 가이드북 2027의 기출과 생기부 예상 질문 규칙으로 합니다.\"}},{\"@type\":\"Question\",\"name\":\"경기대학교 면접은 어떤 형태인가요?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"경기대 KGU학생부종합전형은 서류기반 면접입니다. SW우수자전형은 서류기반 면접. 디자인학부는 과제 제시 발표와 서류기반 혼합 면접. 준비는 경기대 면접 가이드북 2027의 기출과 생기부 예상 질문 규칙으로 합니다.\"}},{\"@type\":\"Question\",\"name\":\"경북대학교 면접은 어떤 형태인가요?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"경북대 지역인재전형은 서류기반 면접입니다. 지역의사선발전형은 서류기반과 인적성 혼합 면접. 경북대 2027 면접 가이드북은 준비 중이며 판매 개시는 공지로 알립니다.\"}},{\"@type\":\"Question\",\"name\":\"경희대학교 면접은 어떤 형태인가요?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"경희대 네오르네상스전형은 서류기반 면접입니다. 준비는 경희대 면접 가이드북 2027의 기출과 생기부 예상 질문 규칙으로 합니다.\"}},{\"@type\":\"Question\",\"name\":\"고려대학교 면접은 어떤 형태인가요?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"고려대(고대) 계열적합전형은 제시문 면접입니다. 고른기회전형은 제시문 면접. 준비는 고려대 제시문 면접 스튜디오에서 기출 지문으로 모의면접을 봅니다.\"}},{\"@type\":\"Question\",\"name\":\"광운대학교 면접은 어떤 형태인가요?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"광운대 광운참빛인재전