book/inha.html\"},{\"@type\":\"ListItem\",\"position\":29,\"name\":\"중앙대학교 2027 면접 가이드북\",\"url\":\"https://hyunhak.com/guidebook/cau.html\"},{\"@type\":\"ListItem\",\"position\":30,\"name\":\"한국외국어대학교 2027 면접 가이드북\",\"url\":\"https://hyunhak.com/guidebook/hufs.html\"},{\"@type\":\"ListItem\",\"position\":31,\"name\":\"한양대학교(ERICA) 2027 면접 가이드북\",\"url\":\"https://hyunhak.com/guidebook/hanyang-erica.html\"},{\"@type\":\"ListItem\",\"position\":32,\"name\":\"연세대학교 제시문 면접 스튜디오 (활동우수형)\",\"url\":\"https://hyunhak.com/programs/yonsei.html\"},{\"@type\":\"ListItem\",\"position\":33,\"name\":\"고려대학교 제시문 면접 스튜디오 (계열적합전형)\",\"url\":\"https://hyunhak.com/programs/korea.html\"}]}]}</script>\ninterview.html:39:main p,.sh p,.phead .lede,.aeo-answer,details.faq .a{max-width:none}\ninterview.html:109:  <!-- aeo --><p class=\"aeo-answer\">대학 면접은 서류기반 면접(생기부 면접), 제시문 면접, MMI 로 갈립니다. 38개 대학 중 34곳이 서류기반, 연세대와 고려대는 제시문 면접이며 표에서 전형별로 확인합니다.</p><!-- /aeo -->\nlectures/yonsei-intl.html:132:<!-- aeo --><p class=\"aeo-answer\">연세대 국제형 풀이법 인강은 공통 풀이 4편과 단위 강의, 세트 해설 30편으로 구성되며 단위 전권 이용권에 포함되어 구매일부터 3개월 시청합니다.</p><!-- /aeo -->\nassets/base.css:365::where(body.v2) .aeo-answer{font-size:var(--t-sm);line-height:var(--lh-body);color:var(--gray);margin-top:var(--s3);max-width:var(--measure)}\n_design/studio_detail_20260903/build/page.css:78:.hero .aeo-answer{font-size:var(--t-sm);color:var(--gray);margin-top:var(--s4);max-width:34em}\nlectures/korea-sci.html:132:<!-- aeo --><p class=\"aeo-answer\">고려대 계열적합 자연 풀이법 인강은 공통 풀이 4편과 단위 강의, 세트 해설 30편으로 구성되며 단위 전권 이용권에 포함되어 구매일부터 3개월 시청합니다.</p><!-- /aeo -->\nstudio.html:97:  <!-- aeo --><p class=\"aeo-answer\">제시문 면접 스튜디오는 연세대, 고려대 제시문을 온라인으로 응시하고 세 단 첨삭을 받는 대입 모의면접 과정입니다. 지문 1편 33,000원, 단위 전권 495,000원 인강 포함.</p><!-- /aeo -->\n_design/gbcard_20260904/opt_b.html:115:  <!-- aeo --><p class=\"aeo-answer\">대학별 면접 가이드북 2027은 31개 대학, 권당 33,000원입니다. 대학마다 면접 형태 판정, 실제 기출, 생기부 질문 규칙, 준비 전략을 담았고 보안 리더로 열람합니다.</p><!-- /aeo -->\n_tools/interview_hub_v1.html:15:main p,.sh p,.phead .lede,.aeo-answer,details.faq .a{max-width:none}\nprograms/studio.html:113:.hero .aeo-answer{font-size:var(--t-sm);color:var(--gray);margin-top:var(--s4);max-width:34em}\nprograms/studio.html:509:  <!-- aeo --><p class=\"aeo-answer\">제시문 면접 스튜디오는 연세대, 고려대 기출 규격 150세트를 촬영 응시하고 세 단 첨삭을 받는 대입 모의면접 과정입니다. 단위 전권 495,000원 인강 포함, 지문 1편 33,000원.</p><!-- /aeo -->\n_tools/guidebook_page_v3.html:92:main p,.sh p,.phead .lede,.aeo-answer,details.faq .a,.parts .d{max-width:none}\n_design/gbcard_20260904/_base.html:119:  <!-- aeo --><p class=\"aeo-answer\">대학별 면접 가이드북 2027은 31개 대학, 권당 33,000원입니다. 대학마다 면접 형태 판정, 실제 기출, 생기부 질문 규칙, 준비 전략을 담았고 보안 리더로 열람합니다.</p><!-- /aeo -->\n_design/gbcard_20260904/opt_c.html:118:  <!-- aeo --><p class=\"aeo-answer\">대학별 면접 가이드북 2027은 31개 대학, 권당 33,000원입니다. 대학마다 면접 형태 판정, 실제 기출, 생기부 질문 규칙, 준비 전략을 담았고 보안 리더로 열람합니다.</p><!-- /aeo -->\nguidebook/dongduk.html:29:<script type=\"application/ld+json\">{\"@context\":\"https://schema.org\",\"@graph\":[{\"@type\":\"Organization\",\"@id\":\"https://hyunhak.com/#organization\",\"name\":\"현학적 연구소\",\"alternateName\":\"玄學的 硏究所\",\"url\":\"https://hyunhak.com/\",\"logo\":{\"@type\":\"ImageObject\",\"url\":\"https://hyunhak.com/assets/photo/art_figure.png\"},\"email\":\"admin@hyunhak.com\",\"telephone\":\"+82-70-8098-0671\",\"taxID\":\"293-38-01827\",\"address\":{\"@type\":\"PostalAddress\",\"streetAddress\":\"테헤란로 70길 12, 402-941A호\",\"addressLocality\":\"강남구\",\"addressRegion\":\"서울특별시\",\"addressCountry\":\"KR\"},\"founder\":{\"@id\":\"https://hyunhak.com/#author\"},\"sameAs\":[]},{\"@type\":\"Person\",\"@id\":\"https://hyunhak.com/#author\",\"name\":\"현건우\",\"url\":\"https://hyunhak.com/about.html\",\"worksFor\":{\"@id\":\"https://hyunhak.com/#organization\"},\"alternateName\":\"현학자\",\"jobTitle\":\"입시 컨설턴트\",\"description\":\"입시 컨설턴트 13년차. 대학별 서류기반면접 가이드북 31권과 연세대, 고려대 제시문 면접 스튜디오를 한 사람이 편집한다.\",\"alumniOf\":{\"@type\":\"CollegeOrUniversity\",\"name\":\"고려대학교\"}},{\"@type\":\"WebSite\",\"@id\":\"ht